  const [form, setForm] = useState({ kind: 'idle', msg: '' });
  const [rsvpFor, setRsvpFor] = useState(null);
  const [rsvpState, setRsvpState] = useState({ kind: 'idle', msg: '' });
  const heroRef = useRef(null);
  const tabRefs = useRef([]);
  const dialogRef = useRef(null);

  useEffect(() => {
    try { const t = localStorage.getItem('tfl-theme'); if (t) setTheme(t); else setTheme('dark'); } catch (e) {}
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      setStickyOn(window.scrollY > 160);
    };
    handleScroll();
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    const d = dialogRef.current;
    if (!d) return;
    if (rsvpFor && !d.open) { d.showModal ? d.showModal() : d.setAttribute('open', ''); }
    if (!rsvpFor && d.open) d.close();
  }, [rsvpFor]);

  const toggleTheme = () => {
    const next = theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
    try { localStorage.setItem('tfl-theme', next); } catch (e) {}
  };

  const selectTab = (i) => { setTab(i); tabRefs.current[i] && tabRefs.current[i].focus(); };

  async function submitEnquiry(e) {
    e.preventDefault();
    const f = e.currentTarget;
    const fd = new FormData(f);
    const data = {
      name: String(fd.get('name') || '').trim(), email: String(fd.get('email') || '').trim(), company: String(fd.get('company') || '').trim(),
      role: fd.get('role'), channels: fd.getAll('channels'), goal: String(fd.get('goal') || '').trim(), website: fd.get('website'),
    };
    if (!data.name) return setForm({ kind: 'err', msg: 'Add your name so we know who to reply to.' });
    if (!EMAIL_RE.test(data.email)) return setForm({ kind: 'err', msg: 'Enter a valid email address, like you@company.com.' });
    if (!data.goal) return setForm({ kind: 'err', msg: 'Tell us in a line what you want to be known for.' });
    setForm({ kind: 'sending', msg: '' });
    const body = `Name: ${data.name}\nEmail: ${data.email}\nCompany: ${data.company}\nRole: ${data.role}\nChannels: ${data.channels.join(', ')}\n\nWhat I want to be known for:\n${data.goal}`;
    const r = await postOrMail(enquiryEndpoint, data, `Enquiry from ${data.name}`, body);
    if (r.ok && r.mailed) setForm({ kind: 'ok', msg: 'Your email app has opened with the enquiry filled in. Press send there to reach us.' });
    else if (r.ok) { f.reset(); setForm({ kind: 'ok', msg: `Thanks, ${data.name.split(' ')[0]}. We'll reply within two working days.` }); }
    else setForm({ kind: 'err', msg: r.errors ? Object.values(r.errors).join(' ') : r.message });
  }

  async function submitRsvp(e) {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const d = { event: rsvpFor.id, name: String(fd.get('name') || '').trim(), email: String(fd.get('email') || '').trim(), website: fd.get('website') };
    if (!d.name) return setRsvpState({ kind: 'err', msg: 'Add your name so we can save your seat.' });
    if (!EMAIL_RE.test(d.email)) return setRsvpState({ kind: 'err', msg: 'Enter a valid email address, like you@company.com.' });
    setRsvpState({ kind: 'sending', msg: '' });
    const r = await postOrMail(rsvpEndpoint, d, `Seat request: ${rsvpFor.title}`, `Name: ${d.name}\nEmail: ${d.email}`);
    if (r.ok && r.mailed) { setRsvpFor(null); return; }
    if (r.ok) { setRsvpState({ kind: 'ok', msg: `Seat saved. We'll email the details to ${d.email}.` }); setTimeout(() => setRsvpFor(null), 1800); }
    else setRsvpState({ kind: 'err', msg: r.errors ? Object.values(r.errors).join(' ') : r.message });
  }

  const openRsvp = (ev) => { setRsvpState({ kind: 'idle', msg: '' }); setRsvpFor(ev); };
  const note = (s) => `form-note${s.kind === 'ok' ? ' ok' : s.kind === 'err' ? ' err' : ''}`;

